# central rectangle
for r in range(2,9):
    for c in range(9,16): grid[r][c]=2
markers=[(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]
for r,c in markers: grid[r][c]=1
# horizontal projection from rectangle, omit each side for which an external marker is present on that row
for r in range(2,9):
    left=any(rr==r and cc<9 for rr,cc in markers)
    right=any(rr==r and cc>15 for rr,cc in markers)
    if not left:
        for c in range(0,9):
            if grid[r][c]==0: grid[r][c]=2
    if not right:
        for c in range(16,20):
            if grid[r][c]==0: grid[r][c]=2
# vertical projection each column, independently each side; suppress a side if marker lies there in that column
for c in range(9,16):
    top=any(cc==c and rr<2 for rr,cc in markers)
    bottom=any(cc==c and rr>8 for rr,cc in markers)
    if not top:
        for r in range(0,2):
            if grid[r][c]==0: grid[r][c]=2
    if not bottom:
        for r in range(9,20):
            if grid[r][c]==0: grid[r][c]=2
print(len(grid),[len(row) for row in grid])
